// ================================================================
//            PROVIDED TEST HARNESS -- DO NOT EDIT THIS FILE
// ================================================================
// Tests the whole of task 1: your dispatch, my_write, my_exit and
// weighted_avg together.
//
// Input: one or more cases until the end of the input. Each case is n, then
// n lines "marks credits". Each case runs dispatch in a child process, so the
// harness can print the exit code of every case.
#include <stdio.h>
#include <sys/wait.h>
#include <unistd.h>

void dispatch(unsigned long *marks, unsigned long *credits, unsigned long n);

static unsigned long marks[1000], credits[1000];

int main(void) {
    unsigned long n;
    while (scanf("%lu", &n) == 1) {
        if (n > 1000) return 1;
        for (unsigned long i = 0; i < n; i++)
            if (scanf("%lu %lu", &marks[i], &credits[i]) != 2) return 1;
        printf("n = %lu\n", n);
        fflush(stdout);

        pid_t pid = fork();
        if (pid == 0) {
            dispatch(marks, credits, n);
            printf("ERROR: dispatch returned\n");
            fflush(stdout);
            _exit(100);
        }
        int st;
        waitpid(pid, &st, 0);
        if (WIFEXITED(st)) printf("exit code %d\n", WEXITSTATUS(st));
        else printf("crashed (signal %d)\n", WTERMSIG(st));
    }
    return 0;
}
